# Define the variables
x_treatment <- 6.89
x_control <- 8.60

# Define the function to calculate the effect size
effect_size <- function(x_treatment, x_control) {
  if (x_treatment < x_control) {
    return("Yes")
  } else {
    return("No")
  }
}

# Calculate the effect size
result <- effect_size(x_treatment, x_control)

# Print the result
print(result)
